package com.bank.insert;

import java.util.ArrayList;
import java.util.List;

// The target table schema: data columns first, partition columns LAST (positional rule).
class TableSchema {
    final List<String> dataColumns;
    final List<String> partitionColumns;

    TableSchema(List<String> dataColumns, List<String> partitionColumns) {
        this.dataColumns = dataColumns;
        this.partitionColumns = partitionColumns;
    }

    // Full schema in positional order = data columns then partition columns.
    List<String> fullOrder() {
        List<String> all = new ArrayList<>(dataColumns);
        all.addAll(partitionColumns);
        return all;
    }

    int partitionStartIndex() { return dataColumns.size(); }
}
