package com.bank.insert;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

// A DataFrame: an ordered list of columns and rows keyed by column name.
class DataFrameRows {
    final List<String> columns;
    final List<Map<String, Object>> rows = new ArrayList<>();

    DataFrameRows(List<String> columns) { this.columns = columns; }

    void addRow(Object... values) {
        Map<String, Object> row = new LinkedHashMap<>();
        for (int i = 0; i < columns.size(); i++) row.put(columns.get(i), values[i]);
        rows.add(row);
    }

    // Returns values in THIS frame's column order (what insertInto uses positionally).
    List<Object> valuesInOrder(int rowIndex) {
        List<Object> vals = new ArrayList<>();
        for (String c : columns) vals.add(rows.get(rowIndex).get(c));
        return vals;
    }
}
