package com.bank.insert;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.Logger;

// insertInto(): maps DataFrame columns onto the table schema BY POSITION.
class PositionalInserter {
    private static final Logger log = Logger.getLogger(PositionalInserter.class.getName());

    void insertInto(DataFrameRows df, TableSchema schema) {
        List<String> tableOrder = schema.fullOrder();
        if (df.columns.size() != tableOrder.size()) {
            throw new IllegalArgumentException("insertInto requires matching column count");
        }

        // Which DataFrame column lands in the PARTITION position?
        int pIdx = schema.partitionStartIndex();
        String dfColInPartitionPos = df.columns.get(pIdx);
        log.warning(() -> "insertInto maps by POSITION. Table partition column is '"
                + schema.partitionColumns.get(0) + "' but DataFrame column in that position is '"
                + dfColInPartitionPos + "'");

        // Count distinct partition directory values = cardinality of the column in partition position.
        Set<Object> distinctPartitionValues = new HashSet<>();
        for (int r = 0; r < df.rows.size(); r++) {
            distinctPartitionValues.add(df.rows.get(r).get(dfColInPartitionPos));
        }
        int dirs = distinctPartitionValues.size();

        // Show the first row mapped by position onto the table columns.
        List<Object> firstRowVals = df.valuesInOrder(0);
        for (int i = 0; i < tableOrder.size(); i++) {
            final int idx = i;
            log.info(() -> "  table column '" + tableOrder.get(idx) + "' <= DataFrame position " + idx
                    + " value=" + firstRowVals.get(idx));
        }
        log.warning(() -> "This write creates " + dirs + " partition directories ("
                + (dirs > 100 ? "EXPLOSION — high cardinality in partition position!" : "ok"));
    }
}
