package com.bank.insert;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Safe pattern: reorder the DataFrame to the table schema BY NAME before inserting.
class SafeInserter {
    private static final Logger log = Logger.getLogger(SafeInserter.class.getName());

    DataFrameRows selectToSchema(DataFrameRows df, TableSchema schema) {
        List<String> order = schema.fullOrder();
        DataFrameRows reordered = new DataFrameRows(order);
        for (Map<String, Object> row : df.rows) {
            List<Object> vals = new ArrayList<>();
            for (String col : order) vals.add(row.get(col)); // pick BY NAME
            reordered.addRow(vals.toArray());
        }
        log.info(() -> "select(" + order + ") applied — DataFrame now matches table order exactly");
        return reordered;
    }

    void insertIntoSafely(DataFrameRows df, TableSchema schema) {
        DataFrameRows aligned = selectToSchema(df, schema);
        new PositionalInserter().insertInto(aligned, schema);
        log.info("Safe insert complete — columns correct, partition count = distinct settlement_date values");
    }
}
