package com.bank.insert;

import java.util.List;
import java.util.logging.Logger;

public class InsertDemo {
    private static final Logger log = Logger.getLogger(InsertDemo.class.getName());

    public static void main(String[] args) {
        // Table: data [trade_id, account_id, amount], partition [settlement_date]
        TableSchema schema = new TableSchema(
            List.of("trade_id", "account_id", "amount"),
            List.of("settlement_date"));

        // BAD DataFrame: refactor reordered columns AND put trade_id in the last (partition) slot.
        DataFrameRows badDf = new DataFrameRows(List.of("amount", "account_id", "settlement_date", "trade_id"));
        badDf.addRow(50000, "SAV2001", "2026-10-30", "TRD-1");
        badDf.addRow(80000, "CUR3001", "2026-10-30", "TRD-2");
        badDf.addRow(30000, "SAV2001", "2026-10-30", "TRD-3");

        log.info("=== Positional insertInto with WRONG order ===");
        new PositionalInserter().insertInto(badDf, schema);

        log.info("=== Safe select-to-schema then insert ===");
        new SafeInserter().insertIntoSafely(badDf, schema);
    }
}
